[18]={class=[[ModuleScript]],source=[[local Manager = {}
local M = require(script.RagdollModule) 


--- Call this module directely if u wanna ragdoll from server
function Manager:Ragdoll(Duration)
	M.Ragdoll(self,Duration)
	if not game.Players:GetPlayerFromCharacter(self) then
		local Hum = self:FindFirstChildWhichIsA("Humanoid")
		Hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp,false)
		Hum:ChangeState(Enum.HumanoidStateType.Physics)
		
		if Duration then
		task.delay(Duration,function()				
		Hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp,true)
		Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
		Hum:SetStateEnabled(Enum.HumanoidStateType.Physics,false)
			
			end)
		end
	
		else
		game.ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("Ragdoll"):FireClient(game.Players:GetPlayerFromCharacter(self),true)
	end
end

function Manager:UnRagdoll(duration)
	M.UnRagdoll(self)
	
	local Hum = self:FindFirstChildWhichIsA("Humanoid")
	Hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp,true)
	Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
	Hum:SetStateEnabled(Enum.HumanoidStateType.Physics,false)
	
end

return Manager
]]},
[19]={class=[[ModuleScript]],source=[[local Ragdoll = {}
function Ragdoll:Ragdoll(Duration)
	self:SetAttribute("qa44eaa7e1ad00eaa", true)
	for i,v in pairs(self:GetDescendants()) do
		if v:IsA("Motor6D")  then
			local Attachment1 = Instance.new("Attachment")
			Attachment1.Name = "RagdollAttach"
			local Attachment2 = Instance.new("Attachment")
			Attachment2.Name = "RagdollAttach"
			
			Attachment1.CFrame = v.C0
			Attachment2.CFrame = v.C1
			Attachment1.Parent = v.Part0
			Attachment2.Parent = v.Part1
			
			local Socket = Instance.new("BallSocketConstraint")
			Socket.Attachment0 = Attachment1
			Socket.Attachment1 = Attachment2
			Socket.LimitsEnabled = true
			Socket.TwistLimitsEnabled = true
			Socket.MaxFrictionTorque = 30
			Socket.Restitution = 0.5
			--Socket.UpperAngle = 25			
			if v.Name == "Right Shoulder" or v.Name == "Left Shoulder" then
				--Socket.TwistUpperAngle = -30
			end
			Socket.Parent = v.Parent
			
			v.Enabled = false
			
			if Duration then 
				task.delay(Duration,function()
					Ragdoll.UnRagdoll(self)
				end)
			end
			
		end
	end
	
	if Duration then
		task.delay(Duration,function()
			Ragdoll.UnRagdoll(self)
		end)
	end
end

function Ragdoll:UnRagdoll()
	self:SetAttribute("qa44eaa7e1ad00eaa", false)
	for i,v in pairs(self:GetDescendants()) do
		if  v.Name == "RagdollAttach" or v:IsA("BallSocketConstraint") then
			v:Destroy()
		elseif v:IsA("Motor6D") then
			v.Enabled = true
		end
	end
	
	--warn("GOT UP")
	
	local Hum = self:FindFirstChildWhichIsA("Humanoid")
	Hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp,true)
	Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
	Hum:SetStateEnabled(Enum.HumanoidStateType.Physics,false)
	
	if game:GetService("Players"):GetPlayerFromCharacter(self) then
		game.ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("Ragdoll"):FireClient(game.Players:GetPlayerFromCharacter(self),false)
	end
end
return Ragdoll
]]},
[20]={class=[[ModuleScript]],source=[[local M={}
function M:playSound(s,p,a,b,c) if not s or not p then return end local q=s:Clone();q.Parent=p;if a then q.TimePosition=a end;if c then q.PlaybackSpeed=c end;q:Play();game:GetService("Debris"):AddItem(q,b or q.TimeLength+1) end
function M:pull(p,c,d,f,r,n,o) if not p then return end local q=Instance.new("Part");q.Transparency=1;q.Size=p.Size;q.Anchored=true;q.CanCollide=false;q.Massless=true;q.CanQuery=false;q.Name=n or "pull_part";q.Parent=p;if typeof(c)=="CFrame" then q.CFrame=(o and o.CFrame or p.CFrame)*c elseif typeof(c)=="Vector3" then q.Position=c end;local a0=Instance.new("Attachment",p);local a1=Instance.new("Attachment",q);local al=Instance.new("AlignPosition",q);al.MaxVelocity=math.huge;al.MaxForce=f;al.Responsiveness=r;al.Attachment0=a0;al.Attachment1=a1;game:GetService("Debris"):AddItem(q,d);game:GetService("Debris"):AddItem(a0,d);game:GetService("Debris"):AddItem(a1,d);return q end
return M]]},
[37]={class=[[ModuleScript]],source=[[local Animator = {}

local ResumeSpeed = 0

function GetOrSetAnimationFolder()
	local folder = game.Workspace:FindFirstChild("AnimatorFolder")
	if folder then
		return folder
	else
		local newFolder = Instance.new("Folder")
		newFolder.Name = "AnimatorFolder"
		newFolder.Parent = workspace
		return newFolder
	end
end

function Animator.PlayAnimation(KeyframeSequence, character)
	if not KeyframeSequence:IsA("KeyframeSequence") then
		print("not a sequence")
		return
	end
	
	if character.Humanoid:FindFirstChild("CurrentAnimation") then
		Animator.StopAnimation(character.Humanoid.CurrentAnimation.Value)
	end
	
	local newAnimation = script.PlayingAnimation:Clone()
	newAnimation:WaitForChild("Speed").Value = 50
	newAnimation:WaitForChild("Target").Value = character
	newAnimation:WaitForChild("AnimationPlayer"):WaitForChild("Origin").Value = newAnimation
	local newKFS = KeyframeSequence:Clone()
	newKFS.Parent = newAnimation
	newAnimation.AnimationPlayer:WaitForChild("Animation").Value = newKFS
	newAnimation.AnimationPlayer:WaitForChild("Rig").Value = character
	newAnimation.Parent = GetOrSetAnimationFolder()
	newAnimation.Disabled = false
	--warn("PLAYING")
	return newAnimation
end

function Animator.StopAnimation(AsamiAnimation)
	if AsamiAnimation:IsA("Script") and AsamiAnimation:FindFirstChild("StopAnimationControl") then
		AsamiAnimation.StopAnimationControl.OnStopCall:Invoke()
		AsamiAnimation:Destroy()
	end
end

function Animator.ChangeAnimationSpeed(AsamiAnimation, speed)
	if AsamiAnimation:IsA("Script") and AsamiAnimation:FindFirstChild("StopAnimationControl") then
		AsamiAnimation.Speed.Value = speed
	end
end

function Animator.StopAnimationOnHumanoid(humanoid)
	if humanoid:FindFirstChild("CurrentAnimation") then
		Animator.StopAnimation(humanoid.CurrentAnimation.Value)
		local player = game:GetService("Players"):GetPlayerFromCharacter(humanoid.Parent)
		if player then
			player.PlayerGui.AnimationPlayer:Destroy()
		end
	end
end

return Animator]]},
[38]={class=[[Script]],source=[[script.StopAnimationControl.Disabled = false

local animationIdentifier = Instance.new("ObjectValue")
animationIdentifier.Value = script
animationIdentifier.Name = "CurrentAnimation"
animationIdentifier.Parent = script.Target.Value.Humanoid

function ReplicateAnimationInPlayer(player)
	local newAnimation = script.AnimationPlayer:Clone()
	newAnimation.Parent = player.PlayerGui
	newAnimation.Disabled = false
end

game.Players.PlayerAdded:Connect(ReplicateAnimationInPlayer)

for i, player in pairs(game.Players:GetPlayers()) do
	ReplicateAnimationInPlayer(player)
end]]},
[39]={class=[[LocalScript]],source=[[--Ty roblox
repeat wait() until script.Parent == game.Players.LocalPlayer.PlayerGui
script.Parent = game.Players.LocalPlayer.PlayerScripts
--

local KeyframeAnimation = script.Animation.Value
local rig = script.Rig.Value
local origin = script.Origin.Value

local keyframeList
if KeyframeAnimation ~= nil then
	keyframeList = KeyframeAnimation:GetKeyframes()
end

local KFNumber = 1
local maxKFNumber
if keyframeList ~= nil then
	maxKFNumber = #keyframeList
end

local basePositions = {}
local lastPositions = {}
local desiredPositions = {}

--FUNCTIONS

local function getJointBetween(part0, part1)
	for _, obj in pairs(part1:GetChildren()) do
		if obj:IsA("Motor6D") and obj.Part0 == part0 then
			return obj
		end
	end
	for _, obj in pairs(part0:GetChildren()) do
		if obj:IsA("Motor6D") and obj.Part1 == part1 then
			return obj
		end
	end
end

function UpdatePositions()
	
	local targetKF = keyframeList[KFNumber]
	
	local function RecursivelyUpdatePositions(parentPose, poseObject)
		if parentPose then
			if rig then
				local FoundParent
				local FoundPoseObject
				for _,p in rig:GetDescendants() do
					if p.Parent:IsA("Accessory") == false and p:IsA("BasePart") then
						if p.Name == parentPose.Name then
							FoundParent = p
						end
						if p.Name == poseObject.Name then
							FoundPoseObject = p
						end
					end
				end
				
				--local FoundParent = rig:FindFirstChild(parentPose.Name, true)
				--local FoundPoseObject = rig:FindFirstChild(poseObject.Name, true)
				if FoundParent and FoundPoseObject then
					local joint = getJointBetween(FoundParent, FoundPoseObject)
					if joint then
					
						--A keyframe Joint was found, proceed with schedulation
						lastPositions[joint] = joint.Transform
						desiredPositions[joint] = poseObject.CFrame
						--
					
					end
				end
			end
		end
		
		for _, subPose in pairs(poseObject:GetSubPoses()) do
			RecursivelyUpdatePositions(poseObject, subPose)
		end
		
	end
	
	if targetKF then
		timeNeeded = targetKF.Time
		
		for _, poseObj in pairs(targetKF:GetPoses()) do
			RecursivelyUpdatePositions(nil, poseObj)
		end
	end
	--timeNeeded = targetKF.Time
end

function ResetJoints()
	for i, v in pairs(basePositions) do
		i.Transform = CFrame.new()
	end
end
--

--CODE RUN
local t = 0
timeNeeded = 0

UpdatePositions()

local AnimatingBind = game["Run Service"].Stepped:Connect(function(totalTime, step)
	
	t = t + (step * origin.Speed.Value)
	local alpha
	if timeNeeded == 0 then
		alpha = 1
	else
		alpha = math.min(1, t / math.max(.001,timeNeeded))
	end
	 
	
	for limb, position in pairs(desiredPositions) do
		limb.Transform = lastPositions[limb]:lerp(desiredPositions[limb], alpha)
		if alpha == 1 then
			lastPositions[limb] = desiredPositions[limb]
		end
	end
	
	if alpha == 1 then
		KFNumber = KFNumber + 1
		if KFNumber > maxKFNumber then
			if KeyframeAnimation.Loop then
				--ResetJoints()
				KFNumber = 1
			else
				ResetJoints()
				script:Destroy()
			end
		end
		
		UpdatePositions()
		t = 0
	end
	
end)
--

--RemoveEvent
origin.StopAnimation.OnClientEvent:Connect(function()
	if origin then
		origin.StopAnimationControl.ConfirmDestruction:FireServer()
	end
	AnimatingBind:Disconnect()
	ResetJoints()
	script:Destroy()
end)
--]]},
[44]={class=[[Script]],source=[[function StopAnimation()
	if script.Parent.Target.Value == nil then return end
	if script.Parent.Target.Value.Humanoid then
		if script.Parent.Target.Value.Humanoid:FindFirstChild("CurrentAnimation") then
			script.Parent.Target.Value.Humanoid.CurrentAnimation:Destroy()
		end
	end
	script.Parent.StopAnimation:FireAllClients()
	script.ConfirmDestruction.OnServerEvent:Connect(function()
		script.Parent:Destroy()
	end)
end

script.OnStopCall.OnInvoke = StopAnimation

script.Parent.Target.Value.Humanoid.Died:Connect(StopAnimation)

local player = game.Players:GetPlayerFromCharacter(script.Parent.Target.Value)

if player then
	player.CharacterRemoving:Connect(StopAnimation)
end]]},
